import java.util.*;

class Solution {
    public List<List<Integer>> allRoutes(int[][] graph) {
        List<List<Integer>> res = new ArrayList<>();
        List<Integer> path = new ArrayList<>();
        path.add(0);
        dfs(graph, 0, path, res);
        return res;
    }

    private void dfs(int[][] g, int v, List<Integer> path, List<List<Integer>> res) {
        if (v == g.length - 1) { res.add(new ArrayList<>(path)); return; } // save a copy
        for (int u : g[v]) {
            path.add(u);
            dfs(g, u, path, res);
            path.remove(path.size() - 1); // backtrack
        }
    }
}

