class Solution:
    def allRoutes(self, graph: List[List[int]]) -> List[List[int]]:
        n = len(graph); out = []; path = [0]
        def go(v):
            if v == n - 1: out.append(path[:]); return
            for u in graph[v]:
                path.append(u); go(u); path.pop()
        go(0)
        return out

